import path from 'node:path';
import {spawn} from 'node:child_process';
import {createServer} from 'node:http';
import {Writable} from 'node:stream';
const root='/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit';
const base='/tmp/codex-tool-runs/svton/m2-audit-20260930';
// Only Docker is replaced: all agent HTTP, auth, job and CLI paths are actual code.
process.env.PATH=`${base}/bin:${process.env.PATH}`;
const {startAgent}=await import(`${root}/dist/agent/server.js`);
const {SecurityStore}=await import(`${root}/dist/agent/security.js`);
const {checkAgent}=await import(`${root}/dist/cli/init/checks.js`);
const {pairMachine}=await import(`${root}/dist/cli/init/pair-flow.js`);
const {writeRegistryCreds}=await import(`${root}/dist/agent/registry-creds.js`);
const {startBundleServer}=await import(`${root}/dist/providers/bundle-server.js`);
const out=[];
const log={info(){},warn(){},error(){},debug(){}};
const tmp=async name=>fs.mkdtemp(`${base}/${name}-`);
function cli(args,cwd,home){return new Promise((resolve,reject)=>{const c=spawn(process.execPath,[`${root}/dist/cli/main.js`,...args],{cwd,env:{...process.env,HOME:home},stdio:['ignore','pipe','pipe']});let stdout='',stderr='';c.stdout.on('data',d=>stdout+=d);c.stderr.on('data',d=>stderr+=d);c.on('error',reject);c.on('exit',code=>resolve({code,stdout,stderr}));});}
async function record(id,fn){try{out.push({id,...await fn()});}catch(e){out.push({id,harnessError:String(e)});}}
const work=await tmp('agent');
const agent=await startAgent({role:'both',token:'FAKE_MASTER',host:'127.0.0.1',port:0,workRoot:work});
async function req(route,token,body,method='POST'){
 const r=await fetch(agent.url+route,{method,headers:{'content-type':'application/json',...(token?{authorization:`Bearer ${token}`}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});return {status:r.status,body:await r.json()};
}
async function mint(role){const s=new SecurityStore(path.join(work,'security.json'));await s.load();const c=await s.createCode(role,15);const x=await req('/api/pairing/exchange',null,{code:c.code});if(x.status!==200)throw Error('fixture exchange');return x.body.token;}
