await record('M2-role-kind-bypass',async()=>{
 const crossWrite=await req('/api/registry-creds',rt,{kind:'push',user:'FAKE_RUNTIME',password:'FAKE_PASS'},'PUT');
 const crossVerify=await req('/api/verify/registry',rt,{mode:'push',registry:'127.0.0.1:59999',namespace:'audit'});
