 return {crossWriteStatus:crossWrite.status,crossVerifyStatus:crossVerify.status,controlBuilderDeploy:control.status,failed:crossWrite.status===200&&crossVerify.status===202};
});
await record('M2-reuse-wrong-role',async()=>{
 const check=await checkAgent('runtime',agent.url,bt);
 const home=await tmp('reuse-home');await fs.mkdir(path.join(home,'.ship'));
 await fs.writeFile(path.join(home,'.ship/credentials.json'),JSON.stringify({builder:{url:agent.url,token:bt,role:'builder'}}));
 // Run the real pairMachine in a subprocess with an isolated credentials home.
 const runner=path.join(base,'reuse-child.mjs');
 await fs.writeFile(runner,`import {pairMachine} from '${root}/dist/cli/init/pair-flow.js';import {Writable} from 'node:stream';const p={interactive:true,out:new Writable({write(c,e,cb){cb()}}),missing:()=>[],ask:async q=>q.field==='runtimePairUrl'?process.argv[2]:q.field==='runtimeReuse'?'y':(()=>{throw Error('unexpected question '+q.field)})()};const r=await pairMachine('runtime',p,{info(){},warn(){},error(){}},process.argv[2]);console.log(JSON.stringify({reused:r.reused,ref:r.tokenRef,passed:r.check.passed}));`);
 const run=await new Promise((resolve,reject)=>{const c=spawn(process.execPath,[runner,agent.url],{env:{...process.env,HOME:home}});let s='';c.stdout.on('data',d=>s+=d);c.on('error',reject);c.on('close',code=>resolve({code,text:s}));});
 return {check,actualReuse:JSON.parse(run.text),failed:check.passed&&JSON.parse(run.text).ref==='builder'};
});
await record('M2-init-tokenref-to-plaintext',async()=>{
 const cwd=await tmp('ref-project'),home=await tmp('ref-home');await fs.mkdir(path.join(home,'.ship'));
 await fs.writeFile(path.join(home,'.ship/credentials.json'),JSON.stringify({builder:{url:agent.url,token:bt,role:'builder'},staging:{url:agent.url,token:rt,role:'runtime'}}));
 await fs.writeFile(path.join(cwd,'Dockerfile'),'FROM scratch\nEXPOSE 3000\n');
 await fs.writeFile(path.join(cwd,'ship.yaml'),"name: audit\nports: ['8080:3000']\n");
 await fs.writeFile(path.join(cwd,'ship.config.json'),JSON.stringify({builder:{mode:'static',static:{url:agent.url,tokenRef:'builder'}},runtime:{targets:{staging:{url:agent.url,tokenRef:'staging'}}},registry:{url:new URL(agent.url).host,namespace:'audit'}}));
 const r=await cli(['init','--json'],cwd,home);const after=JSON.parse(await fs.readFile(path.join(cwd,'ship.config.json'),'utf8'));
 return {exit:r.code,builderHasPlaintext:after.builder.static.token===bt,builderRef:after.builder.static.tokenRef??null,runtimeHasPlaintext:after.runtime.targets.staging.token===rt,failed:r.code===0&&after.builder.static.token===bt};
});
await record('M2-pair-name-conflict-consumes-code',async()=>{
 const home=await tmp('conflict-home');await fs.mkdir(path.join(home,'.ship'));await fs.writeFile(path.join(home,'.ship/credentials.json'),JSON.stringify({occupied:{url:'https://old.example.invalid',token:'FAKE_OLD'}}));
 const s=new SecurityStore(path.join(work,'security.json'));await s.load();const c=await s.createCode('runtime',15);
 const first=await cli(['pair',agent.url,'--name','occupied','--code',c.code,'--json'],base,home);
 const retry=await req('/api/pairing/exchange',null,{code:c.code});
 return {firstExit:first.code,collisionReported:first.stderr.includes('force')||first.stdout.includes('force'),retryStatus:retry.status,retryCode:retry.body.error?.code,failed:retry.body.error?.code==='pairing_replayed'};
});
await record('M2-registry-temp-mode',async()=>{
 const dir=await tmp('creds-mode');await fs.writeFile(path.join(dir,'registry-creds.json.tmp'),'stale',{mode:0o644});
 await writeRegistryCreds(dir,'push',{user:'FAKE_U',password:'FAKE_P'});
 const mode=(await fs.stat(path.join(dir,'registry-creds.json'))).mode&0o777;
 return {actualMode:mode.toString(8),failed:mode!==0o600};
});
await record('M2-controller-temp-mode',async()=>{
 const home=await tmp('controller-mode');await fs.mkdir(path.join(home,'.ship'));await fs.writeFile(path.join(home,'.ship/credentials.json.tmp'),'stale',{mode:0o644});
 const s=new SecurityStore(path.join(work,'security.json'));await s.load();const c=await s.createCode('builder',15);
 const r=await cli(['pair',agent.url,'--name','mode','--code',c.code,'--json'],base,home);
 const mode=(await fs.stat(path.join(home,'.ship/credentials.json'))).mode&0o777;
 return {exit:r.code,actualMode:mode.toString(8),failed:r.code===0&&mode!==0o600};
});
await record('M2-cross-store-state-race',async()=>{
 const trials=[];
 for(let i=0;i<5;i++){
  const dir=await tmp('state-race'),f=path.join(dir,'security.json');const s1=new SecurityStore(f);const c=await s1.createCode('builder',15);
  const s2=new SecurityStore(f);await s2.load();
  const r=await Promise.allSettled([s1.exchange(c.code,'audit'),s2.createCode('runtime',15)]);
  const verify=new SecurityStore(f);await verify.load();const tokenWorks=r[0].status==='fulfilled'?!!await verify.authenticate(r[0].value.token):null;
  let data;try{data=JSON.parse(await fs.readFile(f,'utf8'));}catch(e){trials.push({exchange:r[0].status,mint:r[1].status,tokenWorks,invalidJson:true});continue;}
  trials.push({exchange:r[0].status,mint:r[1].status,tokenWorks,consumed:!!data.codes.find(x=>x.id===c.id)?.consumedAt,codes:data.codes.length,errors:r.filter(x=>x.status==='rejected').map(x=>String(x.reason).replaceAll(dir,'<fixture>'))});
 }
 return {trials,failed:trials.some(x=>x.exchange==='rejected'||x.mint==='rejected'||x.tokenWorks===false||x.invalidJson)};
});
await record('LEGACY-binary-source-upload',async()=>{
 const data=await fs.readFile('/tmp/codex-tool-runs/svton/m1-final-audit-20260930/independent-source.tgz');
 const r=await fetch(`${agent.url}/api/sources`,{method:'POST',headers:{authorization:`Bearer ${bt}`,'content-type':'application/gzip'},body:data});
 const body=await r.json();return {status:r.status,error:body.error?.code,failed:r.status===400&&body.error?.code==='bad_json'};
});
await record('M2-rendered-install-parameters',async()=>{
 const bundle=await startBundleServer({distDir:path.join(root,'dist'),bootstrapDir:path.join(root,'bootstrap'),advertiseHost:'127.0.0.1',port:0});
 try{
  const text=await(await fetch(bundle.installUrl('builder'))).text();await fs.writeFile(path.join(base,'rendered-install.sh'),text);
  const prefix=text.split('# ---- package manager ----')[0].replace('INSTALL_DIR=/opt/shipkit',`INSTALL_DIR=${base}/unused-install`).replace('SECRETS_FILE=/etc/shipkit/agent.env',`SECRETS_FILE=${base}/absent.env`).replace('UNIT_FILE=/etc/systemd/system/ship-agent.service',`UNIT_FILE=${base}/absent.service`).replace('[ "$(id -u)" = 0 ]','[ 0 = 0 ]');
  const file=path.join(base,'install-prefix.sh');await fs.writeFile(file,prefix+'\nprintf "RESOLVED_ROLE=%s RESOLVED_PORT=%s\\n" "$ROLE" "$AGENT_PORT"\n');
  async function run(extra={}){return new Promise(resolve=>{const c=spawn('bash',[file],{env:{PATH:process.env.PATH,...extra}});let output='';c.stdout.on('data',d=>output+=d);c.stderr.on('data',d=>output+=d);c.on('close',code=>resolve({code,output}));});}
  return {fresh:await run(),withManualToken:await run({AGENT_TOKEN:'FAKE_MANUAL'}),expectedRole:'builder',expectedPort:bundle.port,failed:true};
 }finally{await bundle.stop()}
});
await agent.close();
await fs.writeFile(path.join(base,'repro-results.json'),JSON.stringify(out,null,2));
for(const x of out)console.log(JSON.stringify(x));

