import {createServer} from 'node:http';
import {mkdtemp,writeFile,readFile} from 'node:fs/promises';
import {spawn} from 'node:child_process';
const base='/tmp/codex-tool-runs/svton/m2-audit-20260930';
const pkg=`${base}/install-prefix/node_modules/shipkit`;
const server=createServer((req,res)=>{res.setHeader('content-type','application/json');res.end(JSON.stringify({role:'both',docker:true,version:'0.3.0'}));});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const host=`127.0.0.1:${server.address().port}`;
const dir=await mkdtemp(`${base}/package-project-`);
await writeFile(`${dir}/Dockerfile`,'FROM scratch\nEXPOSE 3000\n');
await writeFile(`${dir}/ship.yaml`,"name: package-demo\nports: ['3000:3000']\n");
await writeFile(`${dir}/ship.config.yaml`,JSON.stringify({builder:{mode:'static',static:{url:`http://${host}`,token:'FAKE_PACKAGE_TOKEN'}},registry:{url:host,namespace:'audit'},runtime:{targets:{staging:{url:`http://${host}`,token:'FAKE_PACKAGE_TOKEN'}}}}));
const result=await new Promise(resolve=>{const child=spawn(`${base}/install-prefix/node_modules/.bin/ship`,['init','--json'],{cwd:dir,stdio:['ignore','pipe','pipe']});let out='',err='';child.stdout.on('data',d=>out+=d);child.stderr.on('data',d=>err+=d);child.on('exit',code=>resolve({code,output:JSON.parse(out),stderrHasAnsi:/\x1b\[/.test(err)}));});
server.closeAllConnections();await new Promise(r=>server.close(r));
const {startAgent}=await import(`${pkg}/dist/agent/server.js`);
const agent=await startAgent({host:'127.0.0.1',port:0,role:'runtime',token:'FAKE_PACKAGE_AGENT',workRoot:await mkdtemp(`${base}/package-agent-`)});
const health=await (await fetch(`${agent.url}/health`)).json();await agent.close();
await writeFile(`${base}/package-smoke-results.json`,JSON.stringify({install:'offline isolated prefix; no repository symlink',init:result,installedAgent:{reachable:true,role:health.role,version:health.version},note:'init 使用本地 HTTP 桩；实际 agent 只探测健康接口，不执行 Docker 变更。'},null,2));
console.log(JSON.stringify({initExit:result.code,initOk:result.output.ok,installedAgentRole:health.role,installedAgentVersion:health.version}));

